const contacts = $input.all();
const webhookData = $('Webhook - Campaign Trigger').item.json.body;
const template = webhookData.template || '';
const subject = webhookData.subject || 'Message for you';
const campaignId = webhookData.campaignId || `CAMP-${Date.now()}`;

const results = [];
let index = 0;

for (const contact of contacts) {
  const data = contact.json;
  const email = data.email;
  const name = data.name || data.firstName || 'there';
  const company = data.company || '';
  const role = data.role || '';

  if (!email) continue;

  // Personalize template
  let personalizedBody = template;
  const vars = { name, email, company, role, ...data };
  for (const [key, value] of Object.entries(vars)) {
    if (typeof value === 'string') {
      const regex = new RegExp(`\\{\\{\\s*${key}\\s*\\}\\}`, 'gi');
      personalizedBody = personalizedBody.replace(regex, value);
    }
  }

  let personalizedSubject = subject;
  for (const [key, value] of Object.entries(vars)) {
    if (typeof value === 'string') {
      const regex = new RegExp(`\\{\\{\\s*${key}\\s*\\}\\}`, 'gi');
      personalizedSubject = personalizedSubject.replace(regex, value);
    }
  }

  results.push({
    json: {
      to: email,
      name: name,
      company: company,
      subject: personalizedSubject,
      body: personalizedBody,
      campaignId: campaignId,
      index: index,
      scheduledAt: new Date().toISOString()
    }
  });
  index++;
}

return results;
